begin;
set local statement_timeout='30s';
do $$
declare coach uuid:=gen_random_uuid();other_coach uuid:=gen_random_uuid();pupil uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();
 relation uuid:=gen_random_uuid();other_relation uuid:=gen_random_uuid();second_relation uuid:=gen_random_uuid();
 appointment uuid:=gen_random_uuid();second_appointment uuid:=gen_random_uuid();day date:=current_date+3;j jsonb;notice uuid;before_count bigint;
 old_device uuid:=gen_random_uuid();new_device uuid:=gen_random_uuid();binding uuid:=gen_random_uuid();quiet_device uuid:=gen_random_uuid();job push_private.notice_jobs;
begin
 insert into auth.users(id,email,email_confirmed_at) values(coach,coach||'@appointments.invalid',now()),(other_coach,other_coach||'@appointments.invalid',now()),
 (pupil,pupil||'@appointments.invalid',now()),(outsider,outsider||'@appointments.invalid',now());
 insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),coach,'totp','verified',now(),now()),(gen_random_uuid(),other_coach,'totp','verified',now(),now());
 insert into public.trainer_access(trainer_id,enabled,client_limit,last_reason) values(coach,true,5,'Contrato de citas'),(other_coach,true,5,'Contrato de citas');
 insert into public.trainer_client_relations(id,trainer_id,client_id) values(relation,coach,pupil),(other_relation,other_coach,pupil),(second_relation,coach,outsider);
 perform set_config('request.jwt.claim.sub',coach::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',coach,'role','authenticated','aal','aal1')::text,true);
 set local role authenticated;
 begin perform public.save_trainer_appointment(coach,appointment,0,relation,'Revisión',day,660,45,'Europe/Madrid','Pista',30);raise exception 'AAL1 crea cita';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',coach,'role','authenticated','aal','aal2')::text,true);
 j:=public.save_trainer_appointment(coach,appointment,0,relation,'Revisión',day,660,45,'Europe/Madrid','Pista',30);
 if j->'appointment'->>'id'<>appointment::text or (j->'appointment'->>'student_reminder')::int<>0 then raise exception 'Crea recordatorio sin consentimiento';end if;
 perform public.save_trainer_appointment(coach,appointment,0,relation,'Revisión',day,660,45,'Europe/Madrid','Pista',30);
 j:=public.list_trainer_appointments(coach,day,day);
 if jsonb_array_length(j->'items')<>1 then raise exception 'Duplica cita al reintentar';end if;
 j:=public.save_trainer_appointment(coach,second_appointment,0,second_relation,'Otra cita',day,675,30,'Europe/Madrid','',0);
 if not coalesce((j->>'requires_confirmation')::boolean,false) then raise exception 'No advierte solapamiento';end if;
 reset role;
 if exists(select 1 from trainer_private.appointments where id=second_appointment) then raise exception 'Guarda antes de confirmar solapamiento';end if;
 if (select count(*) from trainer_private.student_notices where source_id=appointment)<>1 then raise exception 'Duplica avisos al reintentar';end if;
 set local role authenticated;
 begin perform public.save_trainer_appointment(coach,appointment,0,relation,'Nueva revisión',day+1,660,45,'Europe/Madrid','Pista',30);raise exception 'Sobrescribe revisión';exception when serialization_failure then null;end;
 perform public.save_trainer_appointment(coach,appointment,1,relation,'Revisión',day+1,690,45,'Europe/Madrid','Pista',30);
 -- El arrastre usa la zona de la agenda y no reinterpreta la zona de la cita.
 reset role;
 insert into push_private.preferences(owner_id,timezone,quiet_enabled) values(coach,'Atlantic/Canary',false);
 set local role authenticated;
 j:=public.move_trainer_appointment(coach,appointment,2,day+2,600);
 if j->'appointment'->>'timezone'<>'Europe/Madrid' or (j->'appointment'->>'duration_minutes')::int<>45
  or (j->'appointment'->>'local_start')::timestamp::time<>'11:00'::time or (j->'appointment'->>'calendar_start')::timestamp::time<>'10:00'::time then raise exception 'Arrastre cambia zona o duración';end if;
 reset role;
 update push_private.settings set enabled=true,firebase_project_id='entrenaop-dev';
 insert into push_private.installations(id,owner_id,secret_hash,binding_id,platform,token,token_hash,appointment_binding,personal_enabled)
 values(old_device,pupil,encode(extensions.digest(repeat('c',64),'sha256'),'hex'),gen_random_uuid(),'android',old_device::text,encode(sha256(convert_to(old_device::text,'UTF8')),'hex'),null,true),
 (new_device,pupil,encode(extensions.digest(repeat('c',64),'sha256'),'hex'),binding,'android',new_device::text,encode(sha256(convert_to(new_device::text,'UTF8')),'hex'),null,true),
 (quiet_device,pupil,encode(extensions.digest(repeat('c',64),'sha256'),'hex'),binding,'android',quiet_device::text,encode(sha256(convert_to(quiet_device::text,'UTF8')),'hex'),binding,false);
 insert into push_private.preferences(owner_id,quiet_enabled) values(pupil,false);
 set local role authenticated;
 perform set_config('request.jwt.claim.sub',other_coach::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other_coach,'role','authenticated','aal','aal2')::text,true);
 begin perform public.get_trainer_appointment(other_coach,appointment);raise exception 'Otro preparador ve cita privada del alumno común';exception when insufficient_privilege then null;end;
 begin perform public.save_trainer_appointment(other_coach,appointment,3,other_relation,'Cambio ajeno',day+1,690,45,'Europe/Madrid','',0);raise exception 'Reasigna cita ajena';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',pupil::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pupil,'role','authenticated','aal','aal1')::text,true);
 j:=public.get_my_appointment(pupil,appointment);
 if not (j->>'can_remind')::boolean then raise exception 'Alumno no consulta cita';end if;
 perform public.enable_my_appointment_notices(pupil,new_device,repeat('c',64),binding);
 begin perform public.enable_my_appointment_notices(pupil,old_device,repeat('c',64),binding);raise exception 'Declara capacidad con binding obsoleto';exception when insufficient_privilege then null;end;
 begin perform 1 from trainer_private.appointments;raise exception 'Alumno lee tabla privada';exception when insufficient_privilege then null;end;
 begin perform trainer_private.appointment_json(appointment);raise exception 'Expone helper sin autorización';exception when insufficient_privilege then null;end;
 j:=public.get_my_trainer_notice_groups(pupil);
 if jsonb_array_length(j->'items')<>0 or (j->>'unread_count')::int<>0 then raise exception 'Rompe feed de app antigua';end if;
 j:=public.get_my_trainer_notice_groups_v2(pupil);
 if jsonb_array_length(j->'items')<>1 or not (j->'resources'->>'has_appointments')::boolean then raise exception 'No agrupa cambios en feed nuevo';end if;
 j:=public.set_my_appointment_reminder(pupil,appointment,3,0,30);
 if (j->>'student_reminder')::int<>30 then raise exception 'No conserva elección del alumno';end if;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'role','authenticated','aal','aal1')::text,true);
 begin perform public.get_my_appointment(outsider,appointment);raise exception 'Alumno ajeno consulta cita';exception when insufficient_privilege then null;end;
 reset role;
 select count(*) into before_count from trainer_private.student_notices where source_id=appointment;
 perform trainer_private.enqueue_appointment_reminders((select starts_at-interval '30 minutes'+interval '1 second' from trainer_private.appointments where id=appointment));
 perform trainer_private.enqueue_appointment_reminders((select starts_at-interval '30 minutes'+interval '1 second' from trainer_private.appointments where id=appointment));
 if (select count(*) from trainer_private.student_notices where source_id=appointment)<>before_count+1 then raise exception 'Recordatorio duplicado o ausente';end if;
 if exists(select 1 from push_private.notice_jobs where installation_id in(old_device,quiet_device)) then raise exception 'Avisa app antigua o dispositivo sin permiso personal';end if;
 select * into job from push_private.notice_jobs where installation_id=new_device;
 if job.id is null then raise exception 'No encola para app preparada y consentida';end if;
 select id into notice from trainer_private.student_notices where source_id=appointment and source_revision%2=1;
 if not trainer_private.appointment_notice_pushable(notice) then raise exception 'Recordatorio válido no se puede despachar';end if;
 update trainer_private.appointments set student_reminder=0 where id=appointment;
 if trainer_private.appointment_notice_pushable(notice) then raise exception 'Envía recordatorio desactivado';end if;
 update trainer_private.appointments set student_reminder=30 where id=appointment;
 perform set_config('request.jwt.claim.sub',coach::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',coach,'role','authenticated','aal','aal2')::text,true);
 set local role authenticated;
 perform public.cancel_trainer_appointment(coach,appointment,3);
 perform public.cancel_trainer_appointment(coach,appointment,3);
 reset role;
 if trainer_private.appointment_notice_pushable(notice) then raise exception 'Envía recordatorio cancelado';end if;
 if not exists(select 1 from trainer_private.appointments where id=appointment and status='cancelled' and revision=4) then raise exception 'Cancelación no idempotente';end if;
 if exists(select 1 from public.scheduled_workouts where user_id in (pupil,outsider)) then raise exception 'Convierte cita en entrenamiento';end if;
 update public.trainer_client_relations set ended_at=clock_timestamp() where id=relation;
 perform set_config('request.jwt.claim.sub',pupil::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',pupil,'role','authenticated','aal','aal1')::text,true);
 set local role authenticated;
 j:=public.get_my_appointment(pupil,appointment);
 if (j->>'can_remind')::boolean then raise exception 'Activa recordatorio de servicio inactivo';end if;
 reset role;update public.trainer_client_relations set ended_at=null where id=relation;
 perform set_config('request.jwt.claim.sub',coach::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',coach,'role','authenticated','aal','aal2')::text,true);
 set local role authenticated;
 begin perform public.save_trainer_appointment(coach,gen_random_uuid(),0,relation,'Hora inexistente','2027-03-28',150,30,'Europe/Madrid','',0);raise exception 'Acepta hueco DST';exception when invalid_parameter_value then null;end;
 set local role anon;
 begin perform public.list_my_appointments(pupil);raise exception 'Anon lee citas';exception when insufficient_privilege then null;end;
 reset role;
end $$;
rollback;
